const TESTED = "Complete example — executed and output-checked in the stated environment at review (Python 3.12 / GCC 13, 15 Nov 2026); the stated output is the real run's output. Not executed inside CyberLab itself — run it in your own lab to see it live.";
type Spec = Omit<Lesson, "version" | "reviewed" | "limitations">;
function L(s: Spec): Lesson { return { ...s, version: V, reviewed: REV, limitations: TESTED }; }

