// ---- Level 4 lesson notes: recap ("What you already know") + Important
// Note (hard idea, easy explanation, everyday analogy) per lesson, EN/BN.
export type L4Note = { recapEn: string; recapBn: string; ideaEn?: string; ideaBn?: string; noteEn?: string; noteBn?: string };
export const L4_NOTES: Record<string, L4Note> = {
  "l4-py-first": { recapEn: "You start from zero — Level 3 gave you the terminal and files; no programming is assumed.", recapBn: "তুমি শূন্য থেকে শুরু করছ — Level 3 তোমাকে terminal ও file দিয়েছে; কোনো programming ধরা হয়নি।" },
  "l4-py-variables": { recapEn: "From the previous lesson: a program runs top to bottom, variables are labelled boxes, print talks, type() names a value.", recapBn: "আগের পাঠ থেকে: program উপর থেকে নিচে চলে, variable নামলেখা বাক্স, print কথা বলে, type() একটি মানের নাম দেয়।",
    ideaEn: "Strings vs numbers", ideaBn: "String বনাম সংখ্যা",
    noteEn: "The same digits can be two different things. \"41\" in quotes is TEXT — you can print it, but adding to it glues text together (\"41\" + \"1\" is \"411\"). 41 without quotes is a NUMBER — arithmetic works. Logs always arrive as text, so every security tool converts deliberately: int(\"41\") makes the number, str(41) makes the text. When a tool misbehaves, check the type first — half of all beginner bugs live in this one distinction.", noteBn: "একই অঙ্ক দুটি আলাদা জিনিস হতে পারে। Quote-এর ভেতর \"41\" হলো লেখা — তা ছাপা যায়, কিন্তু তাতে যোগ করলে লেখা জোড়ে (\"41\" + \"1\" হলো \"411\")। Quote ছাড়া 41 একটি সংখ্যা — হিসাব চলে। Log সবসময় লেখা হিসেবে আসে, তাই প্রতিটি নিরাপত্তা tool সচেতনভাবে রূপান্তর করে: int(\"41\") সংখ্যা বানায়, str(41) লেখা বানায়। একটি tool অদ্ভুত আচরণ করলে আগে type যাচাই করো — beginner bug-এর অর্ধেক এই একটি পার্থক্যে থাকে।" },
  "l4-py-conditions": { recapEn: "From the previous lessons: values have types, text and numbers differ, and programs run their lines in order.", recapBn: "আগের পাঠগুলো থেকে: মানের ধরন আছে, লেখা ও সংখ্যা আলাদা, আর program তার line ক্রমে চালায়।",
    ideaEn: "Why branch order is logic", ideaBn: "Branch-এর ক্রম কেন যুক্তি",
    noteEn: "An if chain is a queue of bouncers: each test checks you in turn, and the FIRST one that says yes walks you in — the rest never see you. So a friendly, general test at the top ('any failure? note it') permanently hides the strict test below it ('new place AND many failures? ALERT'). Rule of thumb for every rule set you will ever write: most serious and most specific first, general last, else for whatever is left.", noteBn: "if chain হলো দারোয়ানের সারি: প্রতিটি test পালা করে তোমাকে যাচাই করে, আর প্রথম যে হ্যাঁ বলে সে-ই ভেতরে নিয়ে যায় — বাকিরা তোমাকে দেখেই না। তাই উপরে একটি বন্ধুত্বপূর্ণ সাধারণ test ('কোনো ব্যর্থতা? লিখে রাখো') তার নিচের কঠোর test-কে স্থায়ীভাবে লুকিয়ে ফেলে ('নতুন জায়গা এবং অনেক ব্যর্থতা? ALERT')। তুমি কখনো লিখবে এমন প্রতিটি নিয়ম-সেটের মূল নিয়ম: সবচেয়ে গুরুতর ও সবচেয়ে নির্দিষ্ট আগে, সাধারণ শেষে, else বাকি সবের জন্য।" },
  "l4-py-control": { recapEn: "From the previous lesson: decisions — comparisons, and/or/not, and first-true-branch chains.", recapBn: "আগের পাঠ থেকে: সিদ্ধান্ত — তুলনা, and/or/not, আর প্রথম-সত্য-branch chain।",
    ideaEn: "Indentation is the grouping", ideaBn: "Indentation-ই দলবদ্ধতা",
    noteEn: "In most languages, braces { } mark which lines belong to a loop or branch. Python uses the SPACES at the start of the line instead — the indented block IS the group. That is why Python code looks clean, and why one missing indent quietly moves a line OUT of the loop (it runs once, at the end) instead of raising an error. When a loop misbehaves, count the spaces before you blame the logic.", noteBn: "বেশিরভাগ ভাষায় brace { } চিহ্নিত করে কোন line গুলো একটি loop বা branch-এর অন্তর্গত। Python বদলে line-এর শুরুর ফাঁক (space) ব্যবহার করে — সাজানো (indented) block-টাই দল। তাই Python code পরিষ্কার দেখায়, আর তাই একটি indent বাদ গেলে একটি line নীরবে loop-এর বাইরে চলে যায় (শেষে একবার চলে) error না দিয়েই। Loop অদ্ভুত আচরণ করলে যুক্তিকে দায়ী করার আগে ফাঁকগুলো গুনো।" },
  "l4-py-functions": { recapEn: "From the previous lessons: variables, strings, decisions, and loops that repeat work.", recapBn: "আগের পাঠগুলো থেকে: variable, string, সিদ্ধান্ত, আর কাজ পুনরাবৃত্তি করা loop।",
    ideaEn: "A function is a named recipe", ideaBn: "Function একটি নামধারী recipe",
    noteEn: "A function packages steps under a name so you can order the whole dish with one word. Parameters are the order slip (what goes in), return is the finished dish handed back (what comes out). The caller never sees the kitchen — and does not need to. Security tools are built this way: a small verdict function like classify(count) can be tested once and then trusted ten thousand times inside a loop.", noteBn: "Function ধাপগুলোকে একটি নামের নিচে গুছিয়ে রাখে যাতে পুরো পদটি এক শব্দে অর্ডার করা যায়। Parameter হলো অর্ডার slip (কী ঢুকবে), return হলো ফিরিয়ে দেওয়া তৈরি পদ (কী বেরোবে)। ডাকনেওয়ালা রান্নাঘর কখনো দেখে না — দেখার দরকারও নেই। নিরাপত্তা tool এভাবেই বানানো: classify(count)-এর মতো একটি ছোট রায়ের function একবার পরীক্ষা করে তারপর একটি loop-এর ভেতর দশ হাজারবার বিশ্বাস করা যায়।" },
  "l4-py-files": { recapEn: "From the previous lessons: loops repeat a check, dictionaries tally results, functions package the steps.", recapBn: "আগের পাঠগুলো থেকে: loop একটি যাচাই পুনরাবৃত্তি করে, dictionary ফল গোনে, function ধাপ গুছিয়ে রাখে.",
    ideaEn: "Stream, don't swallow", ideaBn: "গিলো না, ধারায় পড়ো",
    noteEn: "Reading a whole 4 GB log into memory is trying to drink a reservoir. Streaming — for line in f — is drinking from a tap: one sip at a time, same total water, nothing spills. The code looks identical for a 4-line file and a 4-billion-line file, which is exactly the point: write the shape that survives the biggest input the job can produce, not just the small one in front of you.", noteBn: "পুরো 4 GB log memory-তে পড়া হলো একটি জলাধার পান করার চেষ্টা। Streaming — for line in f — হলো কল থেকে পান করা: একবারে এক ঢোক, মোট পানি একই, কিছু ছলকায় না। Code 4-line file-এর জন্যও একই দেখায়, 4-billion-line file-এর জন্যও — আর সেটাই মূল কথা: এমন আকার লেখো যা কাজের সবচেয়ে বড় input-এও টেকে, শুধু সামনের ছোটটিতে নয়।" },
  "l4-python-security": { recapEn: "From the previous lessons: files stream line by line, and a dictionary can tally anything by name.", recapBn: "আগের পাঠগুলো থেকে: file line ধরে প্রবাহিত হয়, আর dictionary নাম ধরে যেকোনো কিছু গুনতে পারে।" },
  "l4-py-integrity": { recapEn: "From the previous lesson: you can already parse a log and count what matters.", recapBn: "আগের পাঠ থেকে: তুমি ইতিমধ্যে একটি log parse করে যা গুরুত্বপূর্ণ তা গুনতে পারো।",
    ideaEn: "A hash is a fingerprint, not a safe", ideaBn: "Hash আঙুলের ছাপ, সিন্দুক নয়",
    noteEn: "A hash turns any file into a short fingerprint (64 hex characters for SHA-256). Two facts make it useful: the same file always produces the same fingerprint, and changing even one byte produces a completely different one. But a fingerprint cannot rebuild the file — hashing is one-way, unlike encryption, which is a locked box with a key. So a hash proves 'this file is unchanged since the day we recorded the fingerprint' — it never hides the file, and it never proves WHO changed it.", noteBn: "Hash যেকোনো file-কে একটি ছোট আঙুলের ছাপে পরিণত করে (SHA-256-র জন্য 64টি hex character)। দুটি সত্য তাকে কাজের করে: একই file সবসময় একই ছাপ দেয়, আর একটি byte বদলালেও সম্পূর্ণ আলাদা ছাপ আসে। কিন্তু আঙুলের ছাপ দিয়ে file আবার বানানো যায় না — hashing একমুখী, encryption-এর মতো নয়, যা চাবিসহ তালাবদ্ধ বাক্স। তাই hash প্রমাণ করে 'আমরা ছাপটি লিখে রাখার দিন থেকে file অপরিবর্তিত' — তা কখনো file লুকায় না, আর কে বদলেছে তাও প্রমাণ করে না।" },
  "l4-py-network": { recapEn: "From the previous lessons: files, counting, and fingerprints — tools that read local evidence.", recapBn: "আগের পাঠগুলো থেকে: file, গণনা আর আঙুলের ছাপ — স্থানীয় প্রমাণ পড়া tool।",
    ideaEn: "Regex is a shape, not a word", ideaBn: "Regex একটি আকার, শব্দ নয়",
    noteEn: "Searching for the word 'Failed' finds that word. A regex describes a SHAPE — 'four digits, a dash, digits' — and finds anything shaped like it: dates, IPs, ticket numbers in messy lines. Read a regex symbol by symbol ('\\d' = a digit, '+' = one or more of the previous). And a socket is just a phone line between two programs: one side listens, the other calls, bytes travel both ways. HTTP itself is text sent over such a line — which is why your requests code can print the whole conversation.", noteBn: "'Failed' শব্দটি খোঁজা সেই শব্দটিই খুঁজে পায়। Regex একটি আকার বর্ণনা করে — 'চার অঙ্ক, একটি dash, অঙ্ক' — আর ওই আকারের যেকোনো কিছু খোঁজে: এলোমেলো line-এ date, IP, ticket number। Regex চিহ্ন ধরে পড়ো ('\\d' = একটি অঙ্ক, '+' = আগেরটির এক বা একাধিক)। আর socket হলো দুটি program-এর মধ্যে একটি phone line মাত্র: এক পাশ শোনে, অন্য পাশ call করে, byte দুই দিকেই যায়। HTTP নিজে এমন একটি line দিয়েই পাঠানো লেখা — তাই তোমার requests code পুরো কথোপকথন ছাপতে পারে।" },
  "l4-c-basics": { recapEn: "From Python: variables, decisions, loops, functions — every idea returns here, wearing stricter clothes.", recapBn: "Python থেকে: variable, সিদ্ধান্ত, loop, function — প্রতিটি ধারণা এখানে ফিরে আসে, কঠোর পোশাক পরে।",
    ideaEn: "C makes you say the type — and the size", ideaBn: "C তোমাকে type — আর আকার — বলতে বাধ্য করে",
    noteEn: "Python guessed types for you; C asks you to declare them, because C works close to the machine: int score reserves a small fixed box, char buf[16] reserves exactly 16 boxes. Nothing checks whether your text fits those 16 — that freedom is C's speed and C's danger in one sentence. The memory-safety lesson is what happens when the world writes longer text than your box: keep the box sizes of this lesson in mind when you get there.", noteBn: "Python তোমার জন্য type আন্দাজ করত; C তা ঘোষণা করতে বলে, কারণ C machine-এর কাছাকাছি কাজ করে: int score একটি ছোট নির্দিষ্ট বাক্স সংরক্ষণ করে, char buf[16] হুবহু 16টি বাক্স। তোমার লেখা ওই 16টিতে ধরবে কিনা কেউ যাচাই করে না — সেই স্বাধীনতাই C-র গতি ও C-র বিপদ, এক বাক্যে। Memory-safety পাঠ হলো পৃথিবী যখন তোমার বাক্সের চেয়ে লম্বা লেখা লেখে তখন কী হয়: সেখানে পৌঁছালে এই পাঠের বাক্সের আকারগুলো মনে রেখো।" },
  "l4-c-arrays-functions": { recapEn: "From the previous lesson: C types, fixed-size boxes, printf/scanf, and compiled programs.", recapBn: "আগের পাঠ থেকে: C type, নির্দিষ্ট আকারের বাক্স, printf/scanf, আর compile করা program।" },
  "l4-c-pointers": { recapEn: "From the previous lesson: arrays ARE addresses in disguise, and functions receive them.", recapBn: "আগের পাঠ থেকে: array ছদ্মবেশে address-ই, আর function তা গ্রহণ করে।",
    ideaEn: "The postbox rule", ideaBn: "ডাকবাক্সের নিয়ম",
    noteEn: "If pointers ever feel slippery, return to the street: every variable is a postbox, & copies its address onto paper, * walks to the box. Two corollaries cover most bugs: a blank paper (a pointer never given an address) leads nowhere safe, and writing through * changes the BOX, never the paper. Repeat 'the paper is not the box' until it is boring — at that point buffer overflows will read as simple stories about writing past the last box on the row.", noteBn: "Pointer কখনো পিছলা লাগলে রাস্তায় ফিরে যাও: প্রতিটি variable একটি ডাকবাক্স, & তার address কাগজে তোলে, * বাক্স পর্যন্ত হাঁটে। দুটি অনুসিদ্ধান্ত বেশিরভাগ bug ঢেকে দেয়: ফাঁকা কাগজ (কখনো address না পাওয়া pointer) নিরাপদ কোথাও যায় না, আর * দিয়ে লেখা বাক্স বদলায়, কাগজ কখনো নয়। 'কাগজ বাক্স নয়' বিরক্তিকর না হওয়া পর্যন্ত আওড়াও — তখন buffer overflow পড়া যাবে সারির শেষ বাক্স পেরিয়ে লেখার সহজ গল্প হিসেবে।" },
  "l4-c-structs-heap": { recapEn: "From the previous lesson: addresses and pointers — paper that leads to boxes.", recapBn: "আগের পাঠ থেকে: address আর pointer — বাক্সের দিকে যাওয়া কাগজ।",
    ideaEn: "The heap is rented storage", ideaBn: "Heap ভাড়া করা গুদাম",
    noteEn: "Stack variables are hotel rooms booked at compile time: fixed size, released automatically when the function checks out. The heap is rented storage you request WHILE the program runs (malloc), in whatever size the data actually needs — a log line of unknown length, a list that grows. Rent has one rule: you must hand the keys back (free) exactly once. Forget, and the room leaks; hand them back twice, or keep using the room after checkout, and you have two of C's classic bugs — both explored, defensively, in the next lesson.", noteBn: "Stack variable হলো compile time-এ বুক করা hotel room: নির্দিষ্ট আকার, function check-out করলেই স্বয়ংক্রিয়ভাবে ছেড়ে দেওয়া। Heap হলো ভাড়া করা গুদাম যা তুমি program চলার সময় চাও (malloc), data-র সত্যিই যেই আকার লাগে তাতে — অজানা দৈর্ঘ্যের log line, বেড়ে চলা তালিকা। ভাড়ার একটি নিয়ম: চাবি ঠিক একবার ফেরত দিতে হবে (free)। ভুলে গেলে room leak হয়; দুইবার ফেরত দিলে, বা check-out-এর পরে room ব্যবহার চালিয়ে গেলে, C-র দুটি classic bug তোমার হাতে — দুটিই পরের পাঠে defensive ভাবে দেখা হবে।" },
  "l4-c-memory": { recapEn: "From the previous lessons: fixed-size buffers, pointers, structs, and the rented heap.", recapBn: "আগের পাঠগুলো থেকে: নির্দিষ্ট আকারের buffer, pointer, struct, আর ভাড়া করা heap।" },
  "l4-js-basics": { recapEn: "From C: types and discipline. JavaScript relaxes the types but runs somewhere new — inside a web page.", recapBn: "C থেকে: type আর শৃঙ্খলা। JavaScript type শিথিল করে, কিন্তু নতুন জায়গায় চলে — একটি web page-এর ভেতরে।",
    ideaEn: "The page is a tree you can edit", ideaBn: "Page একটি গাছ যা তুমি বদলাতে পারো",
    noteEn: "The browser turns an HTML page into a living tree called the DOM: every heading, button and field is a branch your code can find (getElementById) and change (textContent). An event is the page tapping you on the shoulder — 'the button was clicked' — and your function is what you do about it. The security shadow arrives in the browser lesson: if your code inserts UNTRUSTED text as HTML instead of text, an attacker's text becomes branches of your tree (that is XSS).", noteBn: "Browser একটি HTML page-কে DOM নামের একটি জীবন্ত গাছে পরিণত করে: প্রতিটি heading, button আর field একটি শাখা যা তোমার code খুঁজতে (getElementById) ও বদলাতে (textContent) পারে। Event হলো page তোমার কাঁধে টোকা দেওয়া — 'button চাপা হয়েছে' — আর তোমার function হলো তার উত্তরে তুমি যা করো। নিরাপত্তার ছায়া browser পাঠে আসে: তোমার code অবিশ্বস্ত লেখাকে text-এর বদলে HTML হিসেবে বসালে আক্রমণকারীর লেখা তোমার গাছের শাখা হয়ে যায় (এটাই XSS)।" },
  "l4-js-fetch": { recapEn: "From the previous lesson: variables, objects, functions, the DOM, and events.", recapBn: "আগের পাঠ থেকে: variable, object, function, DOM, আর event।",
    ideaEn: "Async means 'meanwhile'", ideaBn: "Async মানে 'এর মধ্যে'",
    noteEn: "fetch() posts a letter and carries on — the reply arrives LATER, and await is you standing at the door saying 'pause MY errand here until the letter lands, but the rest of the page stays alive'. Without async, a slow server would freeze the whole page. The dangerous confusion is ordering: code written after a fetch may run BEFORE the reply exists, so data-dependent work belongs inside the .then/await flow, not underneath it.", noteBn: "fetch() একটি চিঠি পাঠিয়ে এগিয়ে যায় — জবাব পরে আসে, আর await হলো তুমি দরজায় দাঁড়িয়ে বলছ 'চিঠি না আসা পর্যন্ত আমার কাজ এখানে থামুক, কিন্তু বাকি page জীবন্ত থাকুক'। Async ছাড়া একটি ধীর server পুরো page জমিয়ে দিত। বিপজ্জনক বিভ্রান্তি হলো ক্রম: fetch-এর পরে লেখা code জবাব থাকার আগেই চলতে পারে, তাই data-নির্ভর কাজ .then/await প্রবাহের ভেতরে বসে, তার নিচে নয়।" },
  "l4-javascript-browser": { recapEn: "From the previous lessons: DOM, events, fetch, and promises — the page can now act and talk.", recapBn: "আগের পাঠগুলো থেকে: DOM, event, fetch আর promise — page এখন কাজ করতে ও কথা বলতে পারে।" },
  "l4-bash-automation": { recapEn: "From all three languages: variables, conditions, loops — the shell speaks them as one-line tools.", recapBn: "তিনটি ভাষা থেকে: variable, condition, loop — shell তা এক-line-এর tool হিসেবে বলে।",
    ideaEn: "A pipe is an assembly line", ideaBn: "Pipe একটি assembly line",
    noteEn: "Small tools, one job each, connected by pipes: cat hands lines to grep, grep keeps the matching ones, wc counts what is left. Nothing stores intermediate results — the line flows. When a one-liner confuses you, run it stage by stage, removing one pipe at a time, and watch what each stage passes on. That staged reading is also how analysts audit OTHER people's scripts before running them — a habit that becomes urgent in PowerShell, where a downloaded script can do anything its author wants.", noteBn: "ছোট tool, প্রতিটির একটি কাজ, pipe দিয়ে জোড়া: cat line দেয় grep-কে, grep মেলা গুলো রাখে, wc যা বাকি থাকে গোনে। কিছুই মাঝের ফল জমায় না — line প্রবাহিত হয়। একটি one-liner বিভ্রান্ত করলে তা ধাপে ধাপে চালাও, একবারে একটি pipe সরিয়ে, আর দেখো প্রতিটি ধাপ কী এগিয়ে দেয়। এই ধাপে ধাপে পড়াই analyst-রা অন্যের script চালানোর আগে audit করার উপায় — একটি অভ্যাস যা PowerShell-এ জরুরি হয়ে ওঠে, যেখানে একটি download করা script তার লেখক যা চায় তাই করতে পারে।" },
  "l4-powershell-automation": { recapEn: "From Bash: pipelines and automation — the same ideas, carrying objects instead of text.", recapBn: "Bash থেকে: pipeline আর automation — একই ধারণা, লেখার বদলে object বহন করে।",
    ideaEn: "Objects, not text — and a signature you can check", ideaBn: "Object, লেখা নয় — আর যাচাইযোগ্য একটি স্বাক্ষর",
    noteEn: "Bash pipelines pass TEXT, so every tool re-reads words. PowerShell passes OBJECTS — a stopped service arrives as an object whose .Status you can ask directly, no text-scraping. The power cuts both ways: a downloaded .ps1 can also DO anything. Authenticode signatures are PowerShell's answer — the script carries its publisher's cryptographic signature, and Get-AuthenticodeSignature checks it before you ever press Enter. Unsigned and unknown is a complete sentence: do not run it.", noteBn: "Bash pipeline লেখা পাঠায়, তাই প্রতিটি tool শব্দ আবার পড়ে। PowerShell object পাঠায় — একটি বন্ধ service object হিসেবে আসে যার .Status তুমি সরাসরি জিজ্ঞাসা করতে পারো, কোনো লেখা-খোঁড়া নয়। ক্ষমতা দুই দিকেই কাটে: একটি download করা .ps1-ও যেকোনো কিছু করতে পারে। Authenticode signature PowerShell-এর উত্তর — script তার প্রকাশকের cryptographic স্বাক্ষর বহন করে, আর Get-AuthenticodeSignature তুমি Enter চাপার আগেই তা যাচাই করে। স্বাক্ষরহীন ও অপরিচিত একটি সম্পূর্ণ বাক্য: তা চালাবে না।" },
};

// ---- Tips & Tricks side notes: REAL, lesson-specific tricks only. A
// lesson with no genuine trick is simply absent here — never filler.
export type L4Tips = { en: string[]; bn: string[] };
export const L4_TIPS: Record<string, L4Tips> = {
  "l4-py-first": { en: ["In the Playground, change ONE value at a time and re-run — you will always know which change caused which output change.", "Read code top-to-bottom with your finger on the screen for the first weeks; programs reward literal reading."], bn: ["Playground-এ একবারে একটি মাত্র মান বদলাও, আবার চালাও — কোন বদল কোন output বদলের কারণ তা সবসময় জানবে।", "প্রথম সপ্তাহগুলোতে screen-এ আঙুল রেখে উপর থেকে নিচে code পড়ো; program আক্ষরিক পড়াকে পুরস্কৃত করে।"] },
  "l4-py-variables": { en: ["Name variables after what they hold (failed_count, not x) — future-you reads code far more often than past-you wrote it.", "Trick for the quotes puzzle: if it came from a file, a log, or the keyboard, it is a string until YOU convert it."], bn: ["Variable-এর নাম দাও তা যা ধরে সেই অনুযায়ী (failed_count, x নয়) — ভবিষ্যৎ-তুমি code লেখার চেয়ে অনেক বেশিবার পড়ে।", "Quote ধাঁধার trick: তা file, log বা keyboard থেকে এলে string, যতক্ষণ না তুমি তা রূপান্তর করো।"] },
  "l4-py-conditions": { en: ["Read every condition aloud as an English sentence before running — if the sentence sounds wrong, the branch is wrong.", "Pitfall dodge: write == in conditions from muscle memory by always typing the pair '== ' together; a single = inside if is instantly suspect."], bn: ["চালানোর আগে প্রতিটি condition জোরে একটি বাক্য হিসেবে পড়ো — বাক্য ভুল শোনালে branch ভুল।", "বিপদ এড়ানোর trick: condition-এ == সবসময় '== ' জোড়া হিসেবে একসঙ্গে লিখে অভ্যাস করো; if-এর ভেতর একক = দেখলেই সন্দেহ।"] },
  "l4-py-control": { en: ["Debugging a loop: print the counter INSIDE the loop for one run — watching it step kills most loop confusion in seconds.", "range(5) gives 0..4, not 1..5 — when counts look off by one, suspect the range first."], bn: ["Loop debug করা: একবার চালানোর জন্য counter loop-এর ভেতরে ছাপো — তা ধাপে ধাপে বাড়তে দেখলে বেশিরভাগ loop-জট সেকেন্ডে মরে।", "range(5) দেয় 0..4, 1..5 নয় — গণনা এক ঘর কমবেশি লাগলে আগে range-কে সন্দেহ করো।"] },
  "l4-py-functions": { en: ["Test a new function with three calls: a typical case, zero/empty, and the biggest case you expect — most function bugs live at the edges.", "If a function needs more than ~4 parameters, it is probably doing two jobs — split it."], bn: ["একটি নতুন function তিনটি call দিয়ে পরীক্ষা করো: একটি সাধারণ ক্ষেত্র, শূন্য/খালি, আর তোমার প্রত্যাশিত সবচেয়ে বড় ক্ষেত্র — বেশিরভাগ function bug প্রান্তে থাকে।", "একটি function-এর ~4-এর বেশি parameter লাগলে তা সম্ভবত দুটি কাজ করছে — ভাগ করো।"] },
  "l4-py-files": { en: ["Always .strip() a line before testing it — invisible newlines cause 'impossible' mismatches that waste real analyst hours.", "Open evidence read-only in your head too: if a script of yours contains open(x, \"w\") near a log name, stop and re-read before running."], bn: ["একটি line পরীক্ষার আগে সবসময় .strip() করো — অদৃশ্য newline 'অসম্ভব' অমিল ঘটায় যা আসল analyst-এর ঘণ্টা নষ্ট করে।", "মাথায়ও প্রমাণ read-only খোলো: তোমার script-এ log-এর নামের কাছে open(x, \"w\") থাকলে চালানোর আগে থেমে আবার পড়ো।"] },
  "l4-python-security": { en: ["sorted(counts.items(), key=lambda kv: kv[1], reverse=True) turns your tally into a ranked attacker list in one line — the SOC's favourite view.", "When counts look wrong, print the FIRST parsed line's fields before trusting the totals — parsing bugs show up in line one."], bn: ["sorted(counts.items(), key=lambda kv: kv[1], reverse=True) তোমার গণনাকে এক line-এ ranked আক্রমণকারী তালিকায় পরিণত করে — SOC-র প্রিয় দৃশ্য।", "গণনা ভুল লাগলে মোট বিশ্বাস করার আগে প্রথম parse করা line-এর field গুলো ছাপো — parsing bug line একেই দেখা দেয়।"] },
  "l4-py-integrity": { en: ["Store baselines read-only and OFF the machine they describe — a baseline the attacker can edit proves nothing.", "Compare hashes as strings in code (==), never by eyeballing 64 hex characters; eyes tire, code does not."], bn: ["Baseline read-only রাখো, আর যেই machine-এর বর্ণনা দেয় তার বাইরে রাখো — আক্রমণকারী বদলাতে পারে এমন baseline কিছু প্রমাণ করে না।", "Hash code-এ string হিসেবে তুলনা করো (==), 64 hex character চোখে দেখে কখনো নয়; চোখ ক্লান্ত হয়, code হয় না।"] },
  "l4-py-network": { en: ["Test a regex against three lines — one that must match, one that must not, one that almost matches — before letting it near a real log.", "Set a timeout on EVERY request and socket in real tools; a hanging target should never hang your scanner."], bn: ["Regex আসল log-এর কাছে যেতে দেওয়ার আগে তিনটি line-এ পরীক্ষা করো — একটি যা মিলতেই হবে, একটি যা মিলবে না, একটি যা প্রায় মেলে।", "আসল tool-এ প্রতিটি request ও socket-এ timeout বসাও; একটি ঝুলন্ত target তোমার scanner-কে কখনো ঝুলিয়ে রাখা উচিত নয়।"] },
  "l4-c-basics": { en: ["Compile with -Wall -Wextra from day one and treat warnings as free tutoring — the compiler is pointing at tomorrow's bugs today.", "In printf, count the % specifiers and the arguments after the string: they must match, one for one."], bn: ["প্রথম দিন থেকে -Wall -Wextra দিয়ে compile করো, আর warning-কে বিনামূল্যের শিক্ষক মনে করো — compiler আজই আগামীকালের bug দেখিয়ে দিচ্ছে।", "printf-এ % চিহ্ন আর string-এর পরের argument গুনো: একটির বিপরীতে একটি মিলতে হবে।"] },
  "l4-c-pointers": { en: ["Memory trick that never fails: '%p' prints the paper, '%d' with *p prints the box. Decide which you want before writing the line.", "When lost in pointer code, draw the street: boxes with values, arrows from papers to boxes. Thirty seconds of drawing beats ten minutes of staring."], bn: ["কখনো ব্যর্থ না হওয়া memory trick: '%p' কাগজ ছাপে, *pসহ '%d' বাক্স ছাপে। Line লেখার আগেই ঠিক করো তুমি কোনটা চাও।", "Pointer code-এ হারিয়ে গেলে রাস্তাটি আঁকো: মানসহ বাক্স, কাগজ থেকে বাক্সের দিকে তীর। ত্রিশ সেকেন্ড আঁকা দশ মিনিট তাকিয়ে থাকাকে হারায়।"] },
  "l4-c-structs-heap": { en: ["Pair every malloc with its free IN THE SAME sitting, writing the free first if the code is long — leaked allocations are usually born as 'I will add the free later'.", "After free(p), set p = NULL immediately; a later accidental use then crashes loudly instead of corrupting quietly."], bn: ["প্রতিটি malloc-কে তার free-এর সঙ্গে একই বসায় জোড়া দাও, code লম্বা হলে free-টি আগে লেখো — leak হওয়া allocation সাধারণত 'free পরে যোগ করব' থেকেই জন্মায়।", "free(p)-এর পর সঙ্গে সঙ্গে p = NULL বসাও; পরে ভুলবশত ব্যবহার তখন নীরবে নষ্ট করার বদলে জোরে crash করে।"] },
  "l4-c-memory": { en: ["Use an ASan build (gcc -fsanitize=address) while learning: it names the exact line of an overflow instead of letting it corrupt silently.", "Prefer snprintf(dst, sizeof dst, ...) everywhere — the size argument makes the safe choice enforceable, not aspirational."], bn: ["শেখার সময় ASan build (gcc -fsanitize=address) ব্যবহার করো: তা নীরবে নষ্ট হতে না দিয়ে overflow-এর হুবহু line-এর নাম বলে।", "সব জায়গায় snprintf(dst, sizeof dst, ...) পছন্দ করো — size argument নিরাপদ পছন্দটিকে আকাঙ্ক্ষা নয়, কার্যকরযোগ্য করে।"] },
  "l4-js-basics": { en: ["console.log is the print of the browser — log the variable BEFORE the line that misbehaves, not after.", "Use textContent for untrusted text and innerHTML only for markup you fully control — that single habit prevents most beginner XSS."], bn: ["console.log হলো browser-এর print — যেই line অদ্ভুত আচরণ করে তার আগে variable log করো, পরে নয়।", "অবিশ্বস্ত লেখার জন্য textContent ব্যবহার করো, আর innerHTML শুধু সম্পূর্ণ তোমার নিয়ন্ত্রণের markup-এর জন্য — এই একটি অভ্যাস বেশিরভাগ beginner XSS আটকায়।"] },
  "l4-js-fetch": { en: ["When async output appears in the 'wrong' order, you have found the lesson: log 'before', 'inside await', and 'after' to watch the real sequence.", "Always handle the failure branch (catch / response.ok check) — a header checker that dies on the first unreachable site checks nothing."], bn: ["Async output 'ভুল' ক্রমে এলে তুমি পাঠটি পেয়েছ: 'before', 'inside await', 'after' log করে আসল ক্রম দেখো।", "ব্যর্থতার branch সবসময় সামলাও (catch / response.ok যাচাই) — প্রথম অপৌঁছানো site-এ মরে যাওয়া header checker কিছুই যাচাই করে না।"] },
  "l4-bash-automation": { en: ["Build one-liners stage by stage in the terminal, adding one pipe at a time — the stage where output changes is the stage you misunderstood.", "set -euo pipefail at the top of real scripts: fail loudly on errors and unset variables instead of automating a mistake 10,000 times."], bn: ["One-liner ধাপে ধাপে terminal-এ বানাও, একবারে একটি pipe যোগ করে — যেই ধাপে output বদলায়, সেই ধাপটাই তুমি ভুল বুঝেছিলে।", "আসল script-এর উপরে set -euo pipefail রাখো: error ও unset variable-এ জোরে ব্যর্থ হও, একটি ভুল 10,000 বার automate করার বদলে।"] },
  "l4-powershell-automation": { en: ["Get-AuthenticodeSignature takes ten seconds and is the difference between 'downloaded' and 'trusted' — run it on EVERY third-party script, every time.", "Explore an unfamiliar object with | Get-Member — it lists the properties you can ask for, which beats guessing property names."], bn: ["Get-AuthenticodeSignature দশ সেকেন্ড নেয়, আর তা-ই 'download করা' ও 'বিশ্বস্ত'-এর পার্থক্য — প্রতিটি তৃতীয় পক্ষের script-এ, প্রতিবার চালাও।", "অপরিচিত object | Get-Member দিয়ে খোঁজো — তা তুমি জিজ্ঞাসা করতে পারো এমন property তালিকা দেয়, যা property-র নাম আন্দাজ করাকে হারায়।"] },
  "l4-c-arrays-functions": { en: ["sizeof(arr) / sizeof(arr[0]) counts an array's elements — but ONLY where the array was declared. Passed into a function, an array decays to a pointer and the same expression silently lies; that is why C functions take an explicit length.", "Budget the invisible guest: a 5-letter word needs char word[6], because the terminating '\\0' takes a seat too. Forgetting it is the seed of half the string bugs in the next lessons."], bn: ["sizeof(arr) / sizeof(arr[0]) একটি array-র element গোনে — কিন্তু শুধু যেখানে array ঘোষণা করা হয়েছিল। Function-এ পাঠালে array pointer-এ ক্ষয় হয়, আর একই expression নীরবে মিথ্যা বলে; তাই C function আলাদা length নেয়।", "অদৃশ্য অতিথির জন্য জায়গা রাখো: 5-অক্ষরের শব্দের জন্য char word[6] লাগে, কারণ শেষের '\\0'-ও একটি আসন নেয়। তা ভোলা পরের পাঠগুলোর অর্ধেক string bug-এর বীজ।"] },
  "l4-javascript-browser": { en: ["Open DevTools → Application on any site and look at its cookies: HttpOnly ones are LISTED but their value column stays unreadable to page JavaScript. Seeing that once teaches more than the definition — the flag is doing exactly what the lesson claims.", "Check a page's real defences yourself: view-source and the Network tab's response headers show the site's actual Content-Security-Policy — compare it with the policy this lesson builds."], bn: ["যেকোনো site-এ DevTools → Application খুলে তার cookie দেখো: HttpOnly গুলো তালিকায় থাকে, কিন্তু তাদের মান page-এর JavaScript-এর কাছে অপঠিত থাকে। তা একবার চোখে দেখা সংজ্ঞার চেয়ে বেশি শেখায় — flag হুবহু পাঠের দাবি অনুযায়ী কাজ করছে।", "একটি page-এর আসল প্রতিরক্ষা নিজে যাচাই করো: view-source আর Network tab-এর response header site-এর আসল Content-Security-Policy দেখায় — এই পাঠের বানানো policy-র সঙ্গে মেলাও।"] },
};
